package org.example.behavioral_pattern.strategy_pattern.spring_boot.impl;import org.example.behavioral_pattern.strategy_pattern.spring_boot.ShippingStrategy;import org.example.behavioral_pattern.strategy_pattern.delivery.EShippingType;import org.example.behavioral_pattern.strategy_pattern.delivery.Order;import org.springframework.stereotype.Component;@Componentpublic class StandardShippingStrategy implements ShippingStrategy {    public EShippingType getType() {        return EShippingType.STANDARD;    }    public int calculateFee(Order order) {        return order.getWeightInGram() > 1000 ? 35 : 30;    }}